import { StrictMode, useEffect, useMemo, useRef, useState, type ReactElement } from 'react';
import { createRoot } from 'react-dom/client';
import '@douyinfe/semi-ui/react19-adapter';
import { Button, Input, Layout, Modal, Nav, Popover, Table, Tag, Toast, Typography } from '@douyinfe/semi-ui';
import { IconAlertTriangle, IconArrowRight, IconFile, IconFolder, IconHistogram, IconHome, IconMoon, IconPlay, IconPlus, IconRefresh, IconSearch, IconSetting, IconStop, IconSun, IconUpload } from '@douyinfe/semi-icons';
import '../node_modules/@douyinfe/semi-ui/dist/css/semi.css';
import './styles.css';
import './overrides.css';

type Section = 'overview' | 'projects' | 'troubleshooting' | 'logs' | 'reports' | 'settings';
type Locale = 'zh' | 'en';
type Status = 'stopped' | 'starting' | 'running' | 'restarting' | 'crashed';
interface Command { executable: string; args: string[]; }
interface CommandOption { name: string; command: Command; }
interface RestartPolicy { mode: 'never' | 'on-failure' | 'always'; maxRetries: number; retryDelayMs: number; stableWindowMs: number; }
interface LogPolicy { maxFiles: number; maxBytesPerFile: number; retentionDays: number; }
interface ProjectSettings { startupApplicationIds: string[]; restartPolicy: RestartPolicy; logPolicy: LogPolicy; }
interface Application { id: string; projectId: string; name: string; cwd: string; command: Command; commandOptions: CommandOption[]; selectedCommand: string; status: Status; pid: number | null; restartPolicy: RestartPolicy; logPolicy: LogPolicy; }
interface Project { id: string; name: string; path: string; settings: ProjectSettings; createdAt: string; }
interface EventItem { id: string; type: string; occurredAt: string; detail: Record<string, unknown>; }
interface PreviewApplication { key: string; origin: string; name: string; cwd: string; command: Command; commandOptions: CommandOption[]; selectedCommand: string; restartPolicy: unknown; logPolicy: unknown; warnings: { field: string; reason: string }[]; }
interface Preview { project: { path: string; name: string }; applications: PreviewApplication[]; warnings: { field: string; reason: string }[]; staleApplications?: { id: string; name: string; cwd: string }[]; }
interface DirectoryPreview { root: string; projects: Preview[]; }
interface LogLine { at: string; stream: 'stdout' | 'stderr'; line: string; }
interface Metric { sampledAt: string; pid: number | null; cpuPercent: number | null; uptimeMs: number; restartCount: number; rssBytes: number | null; }
interface DaemonSettings { version: number; stateDirectory: string; sampleIntervalMs: number; retentionDays: number; maxFiles: number; maxBytesPerFile: number; restartPreset: 'balanced' | 'resilient' | 'manual'; }
interface Health { status: string; service: string; version: string; }

/** Versioned, stable-key UI catalog. User choice stays in local browser storage. */
const messages = {
  'page.overview.title': { zh: '运行总览', en: 'Overview' }, 'page.overview.eyebrow': { zh: '本机 Node.js 应用运行状态一目了然', en: 'Local Node.js runtime status at a glance' },
  'page.projects.title': { zh: '项目', en: 'Projects' }, 'page.projects.eyebrow': { zh: '导入、配置并管理本机工作区', en: 'Import, configure, and manage local workspaces' },
  'page.troubleshooting.title': { zh: '排障中心', en: 'Troubleshooting' }, 'page.troubleshooting.eyebrow': { zh: '先处理异常，再深入查看事件与日志', en: 'Resolve failures before inspecting events and logs' },
  'page.logs.title': { zh: '实时日志', en: 'Live logs' }, 'page.logs.eyebrow': { zh: '原始日志保留在本机文件中，显示内容已脱敏', en: 'Raw files stay local; displayed content is redacted' },
  'page.reports.title': { zh: '报表', en: 'Reports' }, 'page.reports.eyebrow': { zh: '基于 24 小时本机聚合数据观察运行趋势', en: 'Review 24-hour local aggregate data' },
  'page.settings.title': { zh: '设置', en: 'Settings' }, 'page.settings.eyebrow': { zh: '本机守护进程和数据保留策略', en: 'Local daemon and data-retention policies' },
  'nav.overview': { zh: '运行总览', en: 'Overview' }, 'nav.projects': { zh: '项目', en: 'Projects' }, 'nav.troubleshooting': { zh: '排障中心', en: 'Troubleshooting' }, 'nav.logs': { zh: '日志', en: 'Logs' }, 'nav.reports': { zh: '报表', en: 'Reports' }, 'nav.settings': { zh: '设置', en: 'Settings' },
  'common.addProject': { zh: '添加项目', en: 'Add project' }, 'common.localHealthy': { zh: '本机服务正常', en: 'Local service healthy' }, 'common.start': { zh: '启动', en: 'Start' }, 'common.stop': { zh: '停止', en: 'Stop' }, 'common.restart': { zh: '重启', en: 'Restart' }, 'common.cancel': { zh: '取消', en: 'Cancel' }, 'common.confirm': { zh: '确认', en: 'Confirm' }
} as const;
const englishPhrases: Record<string, string> = {
  '托管项目': 'Managed projects', '运行应用': 'Running apps', '需排障': 'Needs attention', '本机日志流': 'Local log stream', '实时': 'Live', '当前没有崩溃的应用': 'No crashed applications', '守护进程持续观察已导入的本机进程。': 'The daemon continuously observes imported local processes.', '应用状态': 'Application status', '实时来自本机守护进程': 'Live data from the local daemon', '查看全部': 'View all', '需要关注': 'Needs attention', '先处理异常，再阅读完整日志': 'Resolve failures before reading full logs.', '运行平稳': 'Running smoothly', '启动应用后，这里会汇总崩溃和重启提醒。': 'Crash and restart alerts appear here after an application starts.',
  '从第一个本机项目开始': 'Start with your first local project', 'Dockyard 会扫描 package.json 和静态 PM2 配置，预览后再保存。它不会执行扫描到的配置文件。': 'Dockyard scans package.json and static PM2 configuration, then saves only after review. It never executes scanned configuration.', '扫描项目目录': 'Scan project directory', '选择目录': 'Choose directory', '使用系统文件对话框或输入绝对路径': 'Use the system directory dialog or enter an absolute path', '审核候选项': 'Review candidates', '确认命令、工作目录和 PM2 告警': 'Confirm commands, working directories, and PM2 warnings', '开始托管': 'Begin management', '由守护进程统一管理生命周期和日志': 'The daemon manages lifecycle and logs centrally',
  '添加一个本机目录': 'Add a local directory', '通过系统目录选择器扫描 package.json、工作区和静态 PM2 配置。': 'Use the system directory picker to scan package.json, workspaces, and static PM2 configuration.', '扫描项目': 'Scan project', '应用目录': 'Application directory', '按名称搜索应用': 'Search applications by name', '还没有匹配的应用': 'No matching applications', '扫描并导入一个本机项目后，它会显示在这里。': 'Scan and import a local project to see it here.',
  '崩溃队列': 'Crash queue', '达到重试预算的应用会保留在这里。': 'Applications that exhaust their retry budget remain here.', '生命周期时间线': 'Lifecycle timeline', '选择一个异常应用': 'Select a failing application', '打开日志': 'Open logs', '暂无可显示的事件': 'No events to show', '启动、退出和重启策略决定都会记录在这里。': 'Starts, exits, and restart decisions are recorded here.', '重启应用': 'Restart application', '检查实时日志': 'Inspect live logs',
  '选择应用': 'Select application', '仅显示脱敏后的日志行': 'Only redacted log lines are displayed', '过滤当前日志': 'Filter current logs', '暂停跟随': 'Pause follow', '继续跟随': 'Resume follow', '复制': 'Copy', '正在等待新的 stdout 输出…': 'Waiting for new stdout output…', '正在等待新的 stderr 输出…': 'Waiting for new stderr output…', '请选择一个应用开始跟随日志。': 'Select an application to follow logs.', '没有匹配的日志行。': 'No matching log lines.',
  '总应用数': 'Total applications', '当前运行': 'Running now', '采样窗口': 'Sample window', '本机指标采样': 'Local metric sampling', '仅显示守护进程实际记录的 24 小时聚合数据。': 'Only actual 24-hour aggregate data recorded by the daemon is shown.', '个有数据': ' with data', '最近采样': 'Latest sample', '运行时长': 'Uptime', '重启次数': 'Restart count', '驻留内存': 'Resident memory', '样本数': 'Samples', '暂不可用': 'Unavailable', '等待本机指标采样': 'Waiting for local metric samples', '启动应用后，守护进程会记录运行时长、重启次数和驻留内存；这里不会展示虚构的趋势数据。': 'After an application starts, the daemon records uptime, restart count, and resident memory. No fabricated trend data is shown.',
  '本机守护进程': 'Local daemon', '健康状态和状态目录由实际服务返回。': 'Health and state directory come from the live service.', '绑定地址': 'Bound address', '状态目录': 'State directory', '守护版本': 'Daemon version', '配置版本': 'Configuration version', '日志保留与限制': 'Log retention and limits', '保存后会成为一个新的本机配置版本，并应用到当前已托管应用的日志策略。': 'Saving creates a new local configuration version and applies its log policy to managed applications.', '保留天数': 'Retention days', '归档数量': 'Archive count', '单文件上限 (MB)': 'Maximum file size (MB)', '重启策略预设': 'Restart policy preset', '预设会安全应用到当前应用；停止或重启操作仍始终要求明确确认。': 'The preset safely applies to managed applications; stop and restart still require explicit confirmation.', '平衡：仅失败时重启，最多 5 次': 'Balanced: restart on failure, up to 5 times', '韧性：始终重启，最多 10 次': 'Resilient: always restart, up to 10 times', '手动：不自动重启': 'Manual: never restart automatically', '安全应用设置': 'Safely apply settings', '界面与安全边界': 'Interface and safety boundary', '主题和语言保存在当前浏览器的本机存储。状态目录由启动配置决定，迁移目录需要在守护进程停止后执行，不会在运行中隐式移动日志或数据库。显示到 UI 的日志和命令会脱敏。': 'Theme and language are stored locally in this browser. The state directory is chosen at startup; moving it requires the daemon to stop and never moves logs or the database implicitly. Displayed logs and commands are redacted.', '应用全局运行策略': 'Apply global runtime policy', '确认应用': 'Confirm apply',
  '添加本机项目': 'Add local project', '项目绝对路径': 'Absolute project path', '扫描目录': 'Scan directory', '导入已审核的候选项': 'Import reviewed candidates', '项目已导入。': 'Project imported.', '请选择或输入项目目录。': 'Choose or enter a project directory.'
};
let renderedLocale: Locale = 'zh';
function t(key: keyof typeof messages): string { return messages[key][renderedLocale]; }
const copy: Record<Section, { title: keyof typeof messages; eyebrow: keyof typeof messages }> = {
  overview: { title: 'page.overview.title', eyebrow: 'page.overview.eyebrow' }, projects: { title: 'page.projects.title', eyebrow: 'page.projects.eyebrow' }, troubleshooting: { title: 'page.troubleshooting.title', eyebrow: 'page.troubleshooting.eyebrow' }, logs: { title: 'page.logs.title', eyebrow: 'page.logs.eyebrow' }, reports: { title: 'page.reports.title', eyebrow: 'page.reports.eyebrow' }, settings: { title: 'page.settings.title', eyebrow: 'page.settings.eyebrow' }
};

function DockyardApp(): ReactElement {
  const [section, setSection] = useState<Section>('overview');
  const [dark, setDark] = useState(() => localStorage.getItem('dockyard-theme') === 'dark');
  const [locale, setLocale] = useState<Locale>(() => localStorage.getItem('dockyard-locale') === 'en' ? 'en' : 'zh');
  const [apps, setApps] = useState<Application[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [events, setEvents] = useState<EventItem[]>([]);
  const [logs, setLogs] = useState<LogLine[]>([]);
  const [metrics, setMetrics] = useState<Record<string, Metric[]>>({});
  const [logStream, setLogStream] = useState<'stdout' | 'stderr'>('stdout');
  const [logsPaused, setLogsPaused] = useState(false);
  const [settings, setSettings] = useState<DaemonSettings | null>(null);
  const [health, setHealth] = useState<Health | null>(null);
  const [settingsBusy, setSettingsBusy] = useState(false);
  const [selectedId, setSelectedId] = useState('');
  const [scanOpen, setScanOpen] = useState(false);
  const [path, setPath] = useState('');
  const [preview, setPreview] = useState<Preview | null>(null);
  const [directoryScanOpen, setDirectoryScanOpen] = useState(false);
  const [directoryPath, setDirectoryPath] = useState('');
  const [directoryPreview, setDirectoryPreview] = useState<DirectoryPreview | null>(null);
  const [busy, setBusy] = useState(false);
  const [pendingAction, setPendingAction] = useState<{ app: Application; operation: 'stop' | 'restart' } | null>(null);
  const selected = apps.find((app) => app.id === selectedId) ?? apps[0];
  const crashed = apps.filter((app) => app.status === 'crashed');
  const running = apps.filter((app) => app.status === 'running');
  const projectById = useMemo(() => new Map(projects.map((project) => [project.id, project])), [projects]);

  const refresh = async () => {
    try {
      const [applicationResult, projectResult] = await Promise.all([api<{ applications: Application[] }>('/api/applications'), api<{ projects: Project[] }>('/api/projects')]);
      setApps(applicationResult.applications); setProjects(projectResult.projects);
      setSelectedId((current) => current || applicationResult.applications[0]?.id || '');
    } catch { Toast.error('无法连接本机守护进程。'); }
  };
  useEffect(() => { void refresh(); const interval = section === 'projects' ? Math.max(1_000, settings?.sampleIntervalMs ?? 1_000) : 4_000; const timer = window.setInterval(() => void refresh(), interval); return () => window.clearInterval(timer); }, [section, settings?.sampleIntervalMs]);
  useEffect(() => { void api<DaemonSettings>('/api/settings').then(setSettings).catch(() => undefined); }, []);
  useEffect(() => { localStorage.setItem('dockyard-theme', dark ? 'dark' : 'light'); }, [dark]);
  useEffect(() => { localStorage.setItem('dockyard-locale', locale); document.documentElement.lang = locale === 'zh' ? 'zh-CN' : 'en'; }, [locale]);
  useEffect(() => {
    const replacements = locale === 'en' ? englishPhrases : Object.fromEntries(Object.entries(englishPhrases).map(([zh, en]) => [en, zh]));
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    const nodes: Text[] = []; for (let node = walker.nextNode(); node; node = walker.nextNode()) nodes.push(node as Text);
    for (const node of nodes) { const raw = node.nodeValue ?? ''; const trimmed = raw.trim(); const next = replacements[trimmed]; if (next) node.nodeValue = raw.replace(trimmed, next); }
  });
  useEffect(() => { if (!selected || section !== 'troubleshooting') return; void api<{ events: EventItem[] }>(`/api/applications/${selected.id}/events`).then((result) => setEvents(result.events)).catch(() => setEvents([])); }, [selected?.id, section]);
  useEffect(() => {
    if (!selected || section !== 'logs' || logsPaused) return;
    setLogs([]); const source = new EventSource(`/api/applications/${selected.id}/logs/tail?stream=${logStream}`);
    source.onmessage = (event) => setLogs((current) => [...current.slice(-249), JSON.parse(event.data) as LogLine]);
    source.onerror = () => source.close(); return () => source.close();
  }, [selected?.id, section, logStream, logsPaused]);
  useEffect(() => { if ((section !== 'reports' && section !== 'projects') || !apps.length) return; void Promise.all(apps.map(async (app) => [app.id, (await api<{ metrics: Metric[] }>(`/api/applications/${app.id}/metrics`, { cache: 'no-store' })).metrics] as const)).then((entries) => setMetrics(Object.fromEntries(entries))).catch(() => setMetrics({})); }, [section, apps]);
  useEffect(() => { if (section !== 'settings') return; void Promise.all([api<DaemonSettings>('/api/settings'), api<Health>('/health')]).then(([nextSettings, nextHealth]) => { setSettings(nextSettings); setHealth(nextHealth); }).catch((error) => Toast.error(errorMessage(error))); }, [section]);

  const chooseDirectory = async (onSelected: (value: string) => void) => { setBusy(true); try { const result = await api<{ path: string | null }>('/api/system/select-directory', { method: 'POST' }); if (result.path) onSelected(result.path); } catch (error) { Toast.error(errorMessage(error)); } finally { setBusy(false); } };
  const scan = async () => { if (!path.trim()) return Toast.warning('请选择或输入项目目录。'); setBusy(true); try { setPreview(await api<Preview>('/api/projects/scan', { method: 'POST', body: JSON.stringify({ path, includePm2: true }) })); } catch (error) { Toast.error(errorMessage(error)); } finally { setBusy(false); } };
  const importPreview = async (applications: PreviewApplication[], replaceStale: boolean) => { if (!preview) return; setBusy(true); try { await api('/api/projects/import', { method: 'POST', body: JSON.stringify({ path: preview.project.path, name: preview.project.name, applications, replaceStale }) }); Toast.success('项目已导入。'); setScanOpen(false); setPreview(null); await refresh(); } catch (error) { Toast.error(errorMessage(error)); } finally { setBusy(false); } };
  const scanDirectory = async () => { if (!directoryPath.trim()) return Toast.warning('请选择或输入代码库父目录。'); setBusy(true); try { setDirectoryPreview(await api<DirectoryPreview>('/api/projects/scan-directory', { method: 'POST', body: JSON.stringify({ path: directoryPath, includePm2: true }) })); } catch (error) { Toast.error(errorMessage(error)); } finally { setBusy(false); } };
  const importMany = async (selectedProjects: Preview[]) => { if (!directoryPreview) return; setBusy(true); try { await api('/api/projects/import-many', { method: 'POST', body: JSON.stringify({ root: directoryPreview.root, projects: selectedProjects.map(({ project, applications }) => ({ path: project.path, name: project.name, applications })) }) }); Toast.success(`已导入 ${selectedProjects.length} 个项目。`); setDirectoryScanOpen(false); setDirectoryPreview(null); await refresh(); } catch (error) { Toast.error(errorMessage(error)); } finally { setBusy(false); } };
  const executeAction = async (app: Application, operation: 'start' | 'stop' | 'restart') => { try { await api(`/api/applications/${encodeURIComponent(app.id)}/${operation}`, { method: 'POST' }); await refresh(); } catch (error) { Toast.error(errorMessage(error)); } };
  const action = (app: Application, operation: 'start' | 'stop' | 'restart') => { if (operation === 'start') void executeAction(app, operation); else setPendingAction({ app, operation }); };
  const openProject = () => { setPreview(null); setScanOpen(true); };
  const openProjectDirectory = () => { setDirectoryPreview(null); setDirectoryScanOpen(true); };
  const navigate = (target: Section) => { setSection(target); if (target === 'logs' || target === 'troubleshooting') setSelectedId(selected?.id ?? apps[0]?.id ?? ''); };
  const applySettings = async (draft: Omit<DaemonSettings, 'version' | 'stateDirectory'>) => { setSettingsBusy(true); try { const next = await api<DaemonSettings>('/api/settings', { method: 'PUT', body: JSON.stringify(draft) }); setSettings(next); Toast.success(`设置已安全应用为版本 ${next.version}。`); await refresh(); } catch (error) { Toast.error(errorMessage(error)); } finally { setSettingsBusy(false); } };

  renderedLocale = locale;
  const nav = [{ itemKey: 'overview', text: t('nav.overview'), icon: <IconHome /> }, { itemKey: 'projects', text: t('nav.projects'), icon: <IconFolder /> }, { itemKey: 'troubleshooting', text: t('nav.troubleshooting'), icon: <IconAlertTriangle /> }, { itemKey: 'logs', text: t('nav.logs'), icon: <IconFile /> }, { itemKey: 'reports', text: t('nav.reports'), icon: <IconHistogram /> }];
  return <div key={locale} className={dark ? 'semi-always-dark app-theme' : 'semi-always-light app-theme'}><Layout className="app-shell"><Layout.Sider className="app-sider"><div className="brand"><span className="brand-mark">▰</span><span>Dockyard</span></div><Nav className="primary-nav" selectedKeys={[section]} onSelect={(item) => navigate(item.itemKey as Section)} items={nav} /><div className="sider-spacer" /><Nav className="settings-nav" selectedKeys={section === 'settings' ? ['settings'] : []} onSelect={() => navigate('settings')} items={[{ itemKey: 'settings', text: t('nav.settings'), icon: <IconSetting /> }]} /></Layout.Sider><Layout className="app-main"><Layout.Header className="app-topbar"><div className="topbar-note"><span className="pulse" />{t('common.localHealthy')}</div><Button theme="borderless" onClick={() => setLocale((value) => value === 'zh' ? 'en' : 'zh')}>{locale === 'zh' ? 'EN' : '中文'}</Button><Button theme="borderless" icon={dark ? <IconSun /> : <IconMoon />} onClick={() => setDark((value) => !value)} /></Layout.Header><Layout.Content className="app-content"><header className="page-heading"><div><Typography.Title heading={2}>{t(copy[section].title)}</Typography.Title><Typography.Text type="tertiary">{t(copy[section].eyebrow)}</Typography.Text></div>{section !== 'settings' && <Button theme="solid" size="large" icon={<IconPlus />} onClick={openProject}>{t('common.addProject')}</Button>}</header>{section === 'overview' && <Overview apps={apps} projects={projects} running={running} crashed={crashed} onScan={openProjectDirectory} onNavigate={navigate} onAction={action} projectById={projectById} />}{section === 'projects' && <ProjectsView apps={apps} projects={projects} metrics={metrics} onScan={openProjectDirectory} onAction={action} onRefresh={refresh} />}{section === 'troubleshooting' && <Troubleshooting apps={crashed} selected={selected} events={events} onSelect={setSelectedId} onAction={action} onNavigate={navigate} />}{section === 'logs' && <LogsView apps={apps} selected={selected} logs={logs} stream={logStream} paused={logsPaused} onStream={(stream) => { setLogs([]); setLogStream(stream); }} onPaused={setLogsPaused} onSelect={setSelectedId} />}{section === 'reports' && <ReportsView apps={apps} running={running} crashed={crashed} metrics={metrics} />}{section === 'settings' && <SettingsView settings={settings} health={health} busy={settingsBusy} onApply={applySettings} />}</Layout.Content></Layout></Layout><ScanModal visible={scanOpen} path={path} preview={preview} busy={busy} onPath={setPath} onChoose={() => void chooseDirectory(setPath)} onScan={() => void scan()} onImport={(applications, replaceStale) => void importPreview(applications, replaceStale)} onClose={() => { setScanOpen(false); setPreview(null); }} /><DirectoryScanModal visible={directoryScanOpen} path={directoryPath} preview={directoryPreview} busy={busy} onPath={setDirectoryPath} onChoose={() => void chooseDirectory(setDirectoryPath)} onScan={() => void scanDirectory()} onImport={(projects) => void importMany(projects)} onClose={() => { setDirectoryScanOpen(false); setDirectoryPreview(null); }} /><Modal title={pendingAction?.operation === 'stop' ? '停止应用' : '重启应用'} visible={Boolean(pendingAction)} onCancel={() => setPendingAction(null)} footer={<><Button onClick={() => setPendingAction(null)}>{t('common.cancel')}</Button><Button theme="solid" type={pendingAction?.operation === 'stop' ? 'danger' : 'primary'} onClick={() => { if (pendingAction) void executeAction(pendingAction.app, pendingAction.operation); setPendingAction(null); }}>{pendingAction?.operation === 'stop' ? t('common.stop') : t('common.restart')}</Button></>}>{pendingAction && <Typography.Paragraph>{locale === 'zh' ? `确认要${pendingAction.operation === 'stop' ? '停止' : '重启'} ` : `Confirm ${pendingAction.operation} `}<b>{pendingAction.app.name}</b> {locale === 'zh' ? '吗？守护进程会记录此次生命周期操作。' : '? The daemon records this lifecycle action.'}</Typography.Paragraph>}</Modal></div>;
}

function Overview({ apps, projects, running, crashed, onScan, onNavigate, onAction, projectById }: { apps: Application[]; projects: Project[]; running: Application[]; crashed: Application[]; onScan: () => void; onNavigate: (section: Section) => void; onAction: (app: Application, operation: 'start' | 'stop' | 'restart') => void; projectById: Map<string, Project> }): ReactElement {
  if (!apps.length) return <section className="onboarding"><div className="onboarding-art"><IconFolder size="extra-large" /></div><div><Typography.Title heading={3}>从第一个本机项目开始</Typography.Title><Typography.Paragraph type="tertiary">Dockyard 会扫描 package.json 和静态 PM2 配置，预览后再保存。它不会执行扫描到的配置文件。</Typography.Paragraph><Button theme="solid" size="large" icon={<IconSearch />} onClick={onScan}>扫描项目目录</Button></div><ol><li><b>选择目录</b><span>使用系统文件对话框或输入绝对路径</span></li><li><b>审核候选项</b><span>确认命令、工作目录和 PM2 告警</span></li><li><b>开始托管</b><span>由守护进程统一管理生命周期和日志</span></li></ol></section>;
  return <><section className="stat-grid"><StatCard label="托管项目" value={projects.length} accent="blue" icon={<IconFolder />} /><StatCard label="运行应用" value={running.length} accent="green" icon={<IconPlay />} /><StatCard label="需排障" value={crashed.length} accent="red" icon={<IconAlertTriangle />} /><StatCard label="本机日志流" value="实时" accent="violet" icon={<IconHistogram />} /></section>{crashed.length > 0 ? <section className="attention-banner"><span><IconAlertTriangle /> <b>{crashed.length} 个应用需要排障</b><small>已暂停自动恢复或异常退出，打开事件时间线查看原因。</small></span><Button theme="solid" type="danger" onClick={() => onNavigate('troubleshooting')}>查看原因 <IconArrowRight /></Button></section> : <section className="healthy-banner"><span className="pulse" /><b>当前没有崩溃的应用</b><Typography.Text type="tertiary">守护进程持续观察已导入的本机进程。</Typography.Text></section>}<section className="split-grid"><div className="surface"><div className="surface-heading"><div><Typography.Title heading={5}>应用状态</Typography.Title><Typography.Text type="tertiary">实时来自本机守护进程</Typography.Text></div><Button theme="borderless" onClick={() => onNavigate('projects')}>查看全部</Button></div><ApplicationTable apps={apps.slice(0, 5)} onAction={onAction} projectById={projectById} /></div><div className="surface activity"><div className="surface-heading"><div><Typography.Title heading={5}>需要关注</Typography.Title><Typography.Text type="tertiary">先处理异常，再阅读完整日志</Typography.Text></div></div>{crashed.length ? crashed.map((app) => <div className="attention-item" key={app.id}><Tag color="red">crashed</Tag><div><b>{app.name}</b><span>{app.cwd}</span></div><Button size="small" onClick={() => onNavigate('troubleshooting')}>诊断</Button></div>) : <EmptyHint icon={<IconHistogram />} title="运行平稳" text="启动应用后，这里会汇总崩溃和重启提醒。" />}</div></section></>;
}

function ProjectsView({ apps, projects, metrics, onScan, onAction, onRefresh }: { apps: Application[]; projects: Project[]; metrics: Record<string, Metric[]>; onScan: () => void; onAction: (app: Application, operation: 'start' | 'stop' | 'restart') => void; onRefresh: () => Promise<void> }): ReactElement {
  const [pending, setPending] = useState<{ project: Project; operation: 'stop' | 'restart' | 'delete' } | null>(null);
  const [settingsProject, setSettingsProject] = useState<Project | null>(null);
  const operate = async (project: Project, operation: 'start' | 'stop' | 'restart' | 'delete') => { try { await api(`/api/projects/${encodeURIComponent(project.id)}${operation === 'delete' ? '' : `/${operation}`}`, { method: operation === 'delete' ? 'DELETE' : 'POST' }); Toast.success(operation === 'delete' ? '项目已移除；源码和原始日志未删除。' : '项目操作已请求。'); await onRefresh(); } catch (error) { Toast.error(errorMessage(error)); } };
  const changeCommand = async (application: Application, selectedCommand: string) => { try { await api(`/api/applications/${encodeURIComponent(application.id)}/command`, { method: 'PATCH', body: JSON.stringify({ selectedCommand }) }); Toast.success(`${application.name} 将使用 ${selectedCommand} 启动。`); await onRefresh(); } catch (error) { Toast.error(errorMessage(error)); } };
  return <><section className="import-callout"><div className="callout-icon"><IconUpload /></div><div><b>批量扫描代码库目录</b><Typography.Text type="tertiary">选择例如 ~/Desktop/Company 的父目录；Dockyard 会把第一层代码库分别识别为项目，并批量导入选中的项目。</Typography.Text></div><Button theme="solid" icon={<IconSearch />} onClick={onScan}>批量扫描目录</Button></section><section className="project-list">{projects.map((project) => { const modules = apps.filter((app) => app.projectId === project.id); const startCount = project.settings.startupApplicationIds.length || modules.length; const canStart = modules.some(canStartApplication); const canRestart = modules.some(canRestartApplication); const canStop = modules.some(canStopApplication); return <article className="surface project-workspace" key={project.id}><header className="project-workspace-header"><div><Typography.Title heading={4}>{project.name}</Typography.Title><Typography.Text type="tertiary">{project.path}</Typography.Text><p>{modules.length} 个可运行模块 · {modules.filter((app) => app.status === 'running').length} 个运行中 · 一键启动 {startCount} 个</p></div><div className="row-actions"><Button size="small" icon={<IconPlay />} disabled={!canStart} onClick={() => void operate(project, 'start')}>一键启动</Button><Button size="small" icon={<IconSetting />} onClick={() => setSettingsProject(project)}>项目设置</Button><Button size="small" icon={<IconRefresh />} disabled={!canRestart} onClick={() => setPending({ project, operation: 'restart' })}>重启</Button><Button size="small" type="danger" icon={<IconStop />} disabled={!canStop} onClick={() => setPending({ project, operation: 'stop' })}>停止</Button><Button size="small" type="danger" onClick={() => setPending({ project, operation: 'delete' })}>移除</Button></div></header>{modules.length ? <ProjectApplicationTable apps={modules} metrics={metrics} onAction={onAction} onCommand={changeCommand} /> : <EmptyHint icon={<IconFolder />} title="没有可启动模块" text="此目录仍是一个可配置、可移除的项目。" />}</article>; })}</section><ProjectSettingsModal project={settingsProject} applications={apps.filter((application) => application.projectId === settingsProject?.id)} onClose={() => setSettingsProject(null)} onSaved={async () => { setSettingsProject(null); await onRefresh(); }} /><Modal title={pending?.operation === 'delete' ? '从 Dockyard 移除项目' : `${pending?.operation === 'stop' ? '停止' : '重启'}项目全部应用`} visible={Boolean(pending)} onCancel={() => setPending(null)} footer={<><Button onClick={() => setPending(null)}>取消</Button><Button type={pending?.operation === 'delete' || pending?.operation === 'stop' ? 'danger' : 'primary'} theme="solid" onClick={() => { if (pending) void operate(pending.project, pending.operation); setPending(null); }}>{pending?.operation === 'delete' ? '确认移除元数据' : '确认执行'}</Button></>}>{pending?.operation === 'delete' ? '这只移除 Dockyard 的项目、应用和指标元数据，不会删除代码库目录或原始日志文件。' : '该操作会向项目内每个托管应用发送生命周期请求。'}</Modal></>;
}

function ProjectApplicationTable({ apps, metrics, onAction, onCommand }: { apps: Application[]; metrics: Record<string, Metric[]>; onAction: (app: Application, operation: 'start' | 'stop' | 'restart') => void; onCommand: (app: Application, selectedCommand: string) => Promise<void> }): ReactElement {
  const columns = [
    { title: '应用模块', dataIndex: 'name', width: 240, render: (_: string, application: Application) => <div><b>{application.name}</b><small>{application.cwd}</small></div> },
    { title: '状态', dataIndex: 'status', width: 100, render: (_: Status, application: Application) => <StatusTag status={application.status} /> },
    { title: '启动命令', dataIndex: 'selectedCommand', width: 128, render: (_: string, application: Application) => <CommandTag application={application} onCommand={onCommand} /> },
    { title: 'CPU', key: 'cpu', width: 170, render: (_: unknown, application: Application) => <MetricTrend samples={metrics[application.id] ?? []} kind="cpu" /> },
    { title: '内存', key: 'memory', width: 180, render: (_: unknown, application: Application) => <MetricTrend samples={metrics[application.id] ?? []} kind="memory" /> },
    { title: '实际命令', dataIndex: 'command', width: 160, render: (_: Command, application: Application) => <code>{commandText(application.command)}</code> },
    { title: 'PID', dataIndex: 'pid', width: 76, render: (_: number | null, application: Application) => application.pid ?? '—' },
    { title: '', key: 'actions', width: 270, fixed: 'right' as const, render: (_: unknown, application: Application) => <ApplicationActions app={application} onAction={onAction} /> }
  ];
  return <Table<Application> className="project-module-table" columns={columns} dataSource={apps} rowKey="id" pagination={false} size="small" scroll={{ x: 1324, y: 360 }} />;
}

function MetricTrend({ samples, kind }: { samples: Metric[]; kind: 'cpu' | 'memory' }): ReactElement {
  const values = samples.slice(-24).map((sample) => kind === 'cpu' ? sample.cpuPercent : sample.rssBytes === null ? null : sample.rssBytes / 1_048_576).filter((value): value is number => value !== null && Number.isFinite(value));
  const current = values.at(-1);
  const displayed = useTweenedValue(current ?? 0);
  if (current === undefined) return <span className="metric-unavailable">暂无采样</span>;
  return <div className={`metric-trend ${kind}`}><div><b>{kind === 'cpu' ? `${displayed.toFixed(1)}%` : formatBytes(displayed * 1_048_576)}</b><small>最近采样</small></div><TrendSparkline values={values} tone={kind} /></div>;
}

function TrendSparkline({ values, tone }: { values: number[]; tone: 'cpu' | 'memory' }): ReactElement {
  const chartValues = useTweenedTrend(values);
  const width = 86; const height = 30; const { min, max } = trendDomain(chartValues, tone); const span = Math.max(max - min, 0.01);
  const points = chartValues.map((value, index) => `${(index / Math.max(chartValues.length - 1, 1)) * width},${height - 3 - ((value - min) / span) * (height - 7)}`);
  const line = points.join(' '); const area = `${points[0]} ${points.slice(1).join(' ')} ${width},${height} 0,${height}`;
  return <svg className="trend-sparkline" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`${tone === 'cpu' ? 'CPU' : '内存'}近期趋势`}><polygon className="trend-area" points={area} /><polyline className="trend-line" points={line} /></svg>;
}

function trendDomain(values: number[], tone: 'cpu' | 'memory'): { min: number; max: number } {
  const low = Math.min(...values); const high = Math.max(...values); const range = high - low;
  if (range < 0.001) {
    const padding = tone === 'cpu' ? Math.max(high * 0.1, 0.1) : Math.max(high * 0.02, 1);
    return { min: low - padding, max: high + padding };
  }
  const padding = Math.max(range * 0.16, tone === 'cpu' ? 0.05 : 0.5);
  return { min: Math.max(0, low - padding), max: high + padding };
}

function useTweenedValue(value: number, durationMs = 560): number {
  const [displayed, setDisplayed] = useState(value);
  const displayedRef = useRef(value);
  useEffect(() => {
    const from = displayedRef.current;
    if (from === value) return;
    const startedAt = performance.now(); let frame = 0;
    const tick = (now: number) => { const progress = Math.min(1, (now - startedAt) / durationMs); const eased = 1 - (1 - progress) ** 3; const next = from + (value - from) * eased; displayedRef.current = next; setDisplayed(next); if (progress < 1) frame = requestAnimationFrame(tick); };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [value, durationMs]);
  return displayed;
}

function useTweenedTrend(values: number[], durationMs = 560): number[] {
  const key = values.join(',');
  const target = useMemo(() => normalizeTrend(values), [key]);
  const [displayed, setDisplayed] = useState(target);
  const displayedRef = useRef(target);
  useEffect(() => {
    const from = displayedRef.current;
    if (from.every((value, index) => value === target[index])) return;
    const startedAt = performance.now(); let frame = 0;
    const tick = (now: number) => { const progress = Math.min(1, (now - startedAt) / durationMs); const eased = 1 - (1 - progress) ** 3; const next = from.map((value, index) => value + (target[index]! - value) * eased); displayedRef.current = next; setDisplayed(next); if (progress < 1) frame = requestAnimationFrame(tick); };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [target, durationMs]);
  return displayed;
}

function normalizeTrend(values: number[]): number[] {
  const latest = values.slice(-24);
  const first = latest[0] ?? 0;
  return Array.from({ length: 24 }, (_, index) => latest[Math.max(0, index - (24 - latest.length))] ?? first);
}

function CommandTag({ application, onCommand }: { application: Application; onCommand: (application: Application, selectedCommand: string) => Promise<void> }): ReactElement {
  const canChange = application.status === 'stopped' || application.status === 'crashed';
  return <Popover trigger="hover" position="bottom" condition={canChange && application.commandOptions.length > 1} content={<div className="command-popover"><b>选择启动命令</b>{application.commandOptions.map((option) => <Button key={option.name} size="small" theme="borderless" disabled={option.name === application.selectedCommand} onClick={() => void onCommand(application, option.name)}>{option.name}<code>{commandText(option.command)}</code></Button>)}</div>}><Tag color="green" type="light" className="command-tag">{application.selectedCommand}</Tag></Popover>;
}

function ApplicationActions({ app, onAction }: { app: Application; onAction: (app: Application, operation: 'start' | 'stop' | 'restart') => void }): ReactElement {
  return <div className="row-actions"><Button size="small" icon={<IconPlay />} disabled={!canStartApplication(app)} onClick={() => onAction(app, 'start')}>启动</Button><Button size="small" icon={<IconRefresh />} disabled={!canRestartApplication(app)} onClick={() => onAction(app, 'restart')}>重启</Button><PolicyButton app={app} /><Button size="small" type="danger" icon={<IconStop />} disabled={!canStopApplication(app)} onClick={() => onAction(app, 'stop')}>停止</Button></div>;
}

function canStartApplication(app: Application): boolean { return app.status === 'stopped' || app.status === 'crashed'; }
function canRestartApplication(app: Application): boolean { return app.status === 'running' || app.status === 'crashed'; }
function canStopApplication(app: Application): boolean { return app.status === 'running' || app.status === 'starting' || app.status === 'restarting'; }

function ProjectSettingsModal({ project, applications, onClose, onSaved }: { project: Project | null; applications: Application[]; onClose: () => void; onSaved: () => Promise<void> }): ReactElement {
  const [draft, setDraft] = useState<ProjectSettings | null>(null);
  useEffect(() => setDraft(project ? { ...project.settings, startupApplicationIds: project.settings.startupApplicationIds.length ? [...project.settings.startupApplicationIds] : applications.map((application) => application.id), restartPolicy: { ...project.settings.restartPolicy }, logPolicy: { ...project.settings.logPolicy } } : null), [project?.id]);
  if (!project || !draft) return <Modal visible={false} onCancel={onClose} />;
  const toggleApplication = (id: string, checked: boolean) => setDraft({ ...draft, startupApplicationIds: checked ? [...draft.startupApplicationIds, id] : draft.startupApplicationIds.filter((item) => item !== id) });
  const number = (scope: 'restartPolicy' | 'logPolicy', field: string, value: string | number) => setDraft({ ...draft, [scope]: { ...draft[scope], [field]: Number(value) } });
  const save = async () => { try { await api(`/api/projects/${encodeURIComponent(project.id)}/settings`, { method: 'PATCH', body: JSON.stringify(draft) }); Toast.success('项目一键启动规则和新模块默认策略已保存。'); await onSaved(); } catch (error) { Toast.error(errorMessage(error)); } };
  return <Modal title={`${project.name} 的项目设置`} visible onCancel={onClose} style={{ width: 760 }} footer={<><Button onClick={onClose}>取消</Button><Button theme="solid" onClick={() => void save()}>保存项目规则</Button></>}><Typography.Paragraph type="tertiary">项目规则决定一键启动哪些模块，并设置后续导入模块的默认守护与日志策略；已有模块保留自己的策略，可在模块行内单独调整。</Typography.Paragraph><div className="project-settings-section"><b>一键启动模块</b>{applications.map((application) => <label className="startup-rule" key={application.id}><input type="checkbox" checked={draft.startupApplicationIds.includes(application.id)} onChange={(event) => toggleApplication(application.id, event.target.checked)} /><span>{application.name} · {application.selectedCommand}</span></label>)}</div><div className="directory-input"><label>默认重启模式<select value={draft.restartPolicy.mode} onChange={(event) => setDraft({ ...draft, restartPolicy: { ...draft.restartPolicy, mode: event.target.value as RestartPolicy['mode'] } })}><option value="never">never</option><option value="on-failure">on-failure</option><option value="always">always</option></select></label><label>默认最大重试<Input type="number" value={String(draft.restartPolicy.maxRetries)} onChange={(value) => number('restartPolicy', 'maxRetries', value)} /></label><label>默认退避 (ms)<Input type="number" value={String(draft.restartPolicy.retryDelayMs)} onChange={(value) => number('restartPolicy', 'retryDelayMs', value)} /></label><label>默认稳定窗口 (ms)<Input type="number" value={String(draft.restartPolicy.stableWindowMs)} onChange={(value) => number('restartPolicy', 'stableWindowMs', value)} /></label></div><div className="directory-input"><label>默认日志文件数<Input type="number" value={String(draft.logPolicy.maxFiles)} onChange={(value) => number('logPolicy', 'maxFiles', value)} /></label><label>默认单文件字节数<Input type="number" value={String(draft.logPolicy.maxBytesPerFile)} onChange={(value) => number('logPolicy', 'maxBytesPerFile', value)} /></label><label>默认保留天数<Input type="number" value={String(draft.logPolicy.retentionDays)} onChange={(value) => number('logPolicy', 'retentionDays', value)} /></label></div></Modal>;
}

function Troubleshooting({ apps, selected, events, onSelect, onAction, onNavigate }: { apps: Application[]; selected?: Application; events: EventItem[]; onSelect: (id: string) => void; onAction: (app: Application, operation: 'start' | 'stop' | 'restart') => void; onNavigate: (section: Section) => void }): ReactElement { return <section className="diagnostics-grid"><div className="surface"><div className="surface-heading"><div><Typography.Title heading={5}>崩溃队列</Typography.Title><Typography.Text type="tertiary">达到重试预算的应用会保留在这里。</Typography.Text></div></div>{apps.length ? apps.map((app) => <button className={`crash-row ${selected?.id === app.id ? 'selected' : ''}`} key={app.id} onClick={() => onSelect(app.id)}><Tag color="red">crashed</Tag><span><b>{app.name}</b><small>{app.cwd}</small></span><IconArrowRight /></button>) : <EmptyHint icon={<IconAlertTriangle />} title="没有待处理的崩溃" text="一旦应用因策略暂停，Dockyard 会在这里说明原因。" />}</div><div className="surface"><div className="surface-heading"><div><Typography.Title heading={5}>生命周期时间线</Typography.Title><Typography.Text type="tertiary">{selected ? selected.name : '选择一个异常应用'}</Typography.Text></div>{selected && <Button size="small" onClick={() => onNavigate('logs')}>打开日志</Button>}</div>{selected && events.length ? <div className="timeline">{events.map((event) => <div className="timeline-item" key={event.id}><span className="timeline-dot" /><div><b>{event.type}</b><small>{new Date(event.occurredAt).toLocaleString()}</small><code>{Object.entries(event.detail).map(([key, value]) => `${key}: ${redactText(String(value))}`).join(' · ')}</code></div></div>)}</div> : <EmptyHint icon={<IconRefresh />} title="暂无可显示的事件" text="启动、退出和重启策略决定都会记录在这里。" />}{selected && <div className="panel-actions"><Button theme="solid" icon={<IconRefresh />} onClick={() => onAction(selected, 'restart')}>重启应用</Button><Button onClick={() => onNavigate('logs')}>检查实时日志</Button></div>}</div></section> }

function LogsView({ apps, selected, logs, stream, paused, onStream, onPaused, onSelect }: { apps: Application[]; selected?: Application; logs: LogLine[]; stream: 'stdout' | 'stderr'; paused: boolean; onStream: (stream: 'stdout' | 'stderr') => void; onPaused: (paused: boolean) => void; onSelect: (id: string) => void }): ReactElement {
  const [filter, setFilter] = useState('');
  const visibleLogs = logs.filter((line) => line.line.toLowerCase().includes(filter.toLowerCase()));
  const copyVisible = async () => { try { await navigator.clipboard.writeText(visibleLogs.map((line) => `${line.at} ${redactText(line.line)}`).join('\n')); Toast.success('已复制当前日志视图。'); } catch { Toast.error('浏览器未授予剪贴板权限。'); } };
  return <section className="logs-layout"><div className="surface log-controls"><Typography.Title heading={5}>选择应用</Typography.Title>{apps.map((app) => <button key={app.id} onClick={() => onSelect(app.id)} className={`log-app ${selected?.id === app.id ? 'selected' : ''}`}><span className={`status-dot ${app.status}`} /><span><b>{app.name}</b><small>{app.status}</small></span></button>)}{!apps.length && <Typography.Text type="tertiary">先在项目页导入应用。</Typography.Text>}</div><div className="surface terminal"><div className="surface-heading"><div><Typography.Title heading={5}>{selected ? `${selected.name} · ${stream}` : '实时输出'}</Typography.Title><Typography.Text type="tertiary">仅显示脱敏后的日志行</Typography.Text></div><div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}><select value={stream} onChange={(event) => onStream(event.target.value as 'stdout' | 'stderr')} aria-label="日志流"><option value="stdout">stdout</option><option value="stderr">stderr</option></select><Input value={filter} onChange={setFilter} placeholder="过滤当前日志" style={{ width: 150 }} /><Button size="small" onClick={() => onPaused(!paused)}>{paused ? '继续跟随' : '暂停跟随'}</Button><Button size="small" onClick={() => void copyVisible()} disabled={!visibleLogs.length}>复制</Button><Tag color={paused ? 'grey' : 'green'}>{paused ? 'paused' : 'live'}</Tag></div></div><div className="terminal-body">{visibleLogs.length ? visibleLogs.map((line, index) => <div key={`${line.at}-${index}`}><time>{new Date(line.at).toLocaleTimeString()}</time><span>{redactText(line.line) || ' '}</span></div>) : <span className="terminal-empty">{selected ? (logs.length ? '没有匹配的日志行。' : `正在等待新的 ${stream} 输出…`) : '请选择一个应用开始跟随日志。'}</span>}</div></div></section>;
}

function ReportsView({ apps, running, crashed, metrics }: { apps: Application[]; running: Application[]; crashed: Application[]; metrics: Record<string, Metric[]> }): ReactElement {
  const rows = apps.flatMap((app) => { const samples = metrics[app.id] ?? []; const latest = samples.at(-1); return latest ? [{ app, latest, samples: samples.length }] : []; });
  return <><section className="stat-grid"><StatCard label="总应用数" value={apps.length} accent="blue" icon={<IconFolder />} /><StatCard label="当前运行" value={running.length} accent="green" icon={<IconPlay />} /><StatCard label="崩溃队列" value={crashed.length} accent="red" icon={<IconAlertTriangle />} /><StatCard label="采样窗口" value="24h" accent="violet" icon={<IconHistogram />} /></section><section className="surface"><div className="surface-heading"><div><Typography.Title heading={5}>本机指标采样</Typography.Title><Typography.Text type="tertiary">仅显示守护进程实际记录的 24 小时聚合数据。</Typography.Text></div><Tag color="blue">{rows.length} 个有数据</Tag></div>{rows.length ? <div className="table-wrap"><table className="app-table"><thead><tr><th>应用</th><th>PID</th><th>CPU</th><th>最近采样</th><th>运行时长</th><th>重启次数</th><th>驻留内存</th><th>样本数</th></tr></thead><tbody>{rows.map(({ app, latest, samples }) => <tr key={app.id}><td><b>{app.name}</b><small>{app.cwd}</small></td><td>{latest.pid ?? app.pid ?? '—'}</td><td>{latest.cpuPercent === null ? '暂不可用' : `${latest.cpuPercent.toFixed(1)}%`}</td><td>{new Date(latest.sampledAt).toLocaleString()}</td><td>{formatDuration(latest.uptimeMs)}</td><td>{latest.restartCount}</td><td>{latest.rssBytes === null ? '暂不可用' : formatBytes(latest.rssBytes)}</td><td>{samples}</td></tr>)}</tbody></table></div> : <EmptyHint icon={<IconHistogram />} title="等待本机指标采样" text="启动应用后，守护进程会记录 PID、CPU、运行时长、重启次数和驻留内存；这里不会展示虚构的趋势数据。" />}</section></>;
}

function SettingsView({ settings, health, busy, onApply }: { settings: DaemonSettings | null; health: Health | null; busy: boolean; onApply: (draft: Omit<DaemonSettings, 'version' | 'stateDirectory'>) => Promise<void> }): ReactElement {
  const [draft, setDraft] = useState<DaemonSettings | null>(settings); const [confirming, setConfirming] = useState(false);
  useEffect(() => setDraft(settings), [settings]);
  if (!draft) return <section className="surface"><EmptyHint icon={<IconSetting />} title="正在读取本机设置" text="守护进程会返回当前配置与健康状态。" /></section>;
  const number = (field: 'sampleIntervalMs' | 'retentionDays' | 'maxFiles' | 'maxBytesPerFile', value: string | number) => setDraft({ ...draft, [field]: Number(value) });
  const apply = async () => { await onApply({ sampleIntervalMs: draft.sampleIntervalMs, retentionDays: draft.retentionDays, maxFiles: draft.maxFiles, maxBytesPerFile: draft.maxBytesPerFile, restartPreset: draft.restartPreset }); setConfirming(false); };
  return <section className="settings-grid"><div className="surface"><div className="surface-heading"><div><Typography.Title heading={5}>本机守护进程</Typography.Title><Typography.Text type="tertiary">健康状态和状态目录由实际服务返回。</Typography.Text></div><Tag color={health?.status === 'ok' ? 'green' : 'orange'}>{health?.status ?? 'checking'}</Tag></div><dl><dt>绑定地址</dt><dd>127.0.0.1:4318</dd><dt>状态目录</dt><dd><code>{draft.stateDirectory}</code></dd><dt>守护版本</dt><dd>{health?.version ?? '—'}</dd><dt>配置版本</dt><dd>v{draft.version}</dd></dl></div><div className="surface"><Typography.Title heading={5}>运行时指标采样</Typography.Title><Typography.Paragraph type="tertiary">默认每 1 秒采样一次。确认应用后，守护进程会立刻以新间隔重新采样，项目表也会按同一频率刷新。</Typography.Paragraph><label>采样间隔（秒）<Input type="number" min={1} max={60} value={String(draft.sampleIntervalMs / 1_000)} onChange={(value) => number('sampleIntervalMs', Math.max(1, Number(value)) * 1_000)} /></label></div><div className="surface"><Typography.Title heading={5}>日志保留与限制</Typography.Title><Typography.Paragraph type="tertiary">保存后会成为一个新的本机配置版本，并应用到当前已托管应用的日志策略。</Typography.Paragraph><div className="directory-input"><label>保留天数<Input type="number" value={String(draft.retentionDays)} onChange={(value) => number('retentionDays', value)} /></label><label>归档数量<Input type="number" value={String(draft.maxFiles)} onChange={(value) => number('maxFiles', value)} /></label><label>单文件上限 (MB)<Input type="number" value={String(Math.round(draft.maxBytesPerFile / 1_048_576))} onChange={(value) => number('maxBytesPerFile', Number(value) * 1_048_576)} /></label></div></div><div className="surface"><Typography.Title heading={5}>重启策略预设</Typography.Title><Typography.Paragraph type="tertiary">预设会安全应用到当前应用；停止或重启操作仍始终要求明确确认。</Typography.Paragraph><select value={draft.restartPreset} onChange={(event) => setDraft({ ...draft, restartPreset: event.target.value as DaemonSettings['restartPreset'] })} aria-label="重启策略预设"><option value="balanced">平衡：仅失败时重启，最多 5 次</option><option value="resilient">韧性：始终重启，最多 10 次</option><option value="manual">手动：不自动重启</option></select><div className="panel-actions"><Button theme="solid" loading={busy} onClick={() => setConfirming(true)}>立即应用设置</Button></div></div><div className="surface"><Typography.Title heading={5}>界面与安全边界</Typography.Title><Typography.Paragraph type="tertiary">主题和语言保存在当前浏览器的本机存储。状态目录由启动配置决定，迁移目录需要在守护进程停止后执行，不会在运行中隐式移动日志或数据库。显示到 UI 的日志和命令会脱敏。</Typography.Paragraph></div><Modal title="应用全局运行策略" visible={confirming} onCancel={() => setConfirming(false)} footer={<><Button onClick={() => setConfirming(false)}>取消</Button><Button theme="solid" loading={busy} onClick={() => void apply()}>确认应用</Button></>}>这会创建配置版本 v{draft.version + 1}，立即重新设置指标采样间隔，并更新当前托管应用的日志保留限制和重启预设。不会移动状态目录或删除现有日志。</Modal></section>;
}

function ScanModal({ visible, path, preview, busy, onPath, onChoose, onScan, onImport, onClose }: { visible: boolean; path: string; preview: Preview | null; busy: boolean; onPath: (path: string) => void; onChoose: () => void; onScan: () => void; onImport: (applications: PreviewApplication[], replaceStale: boolean) => void; onClose: () => void }): ReactElement { const [selected, setSelected] = useState<string[]>([]); const [replaceStale, setReplaceStale] = useState(false); useEffect(() => { setSelected(preview?.applications.map((application) => application.key) ?? []); setReplaceStale(false); }, [preview]); const toggle = (key: string, checked: boolean) => setSelected((current) => checked ? [...current, key] : current.filter((item) => item !== key)); const selectedApplications = preview?.applications.filter((application) => selected.includes(application.key)) ?? []; const stale = preview?.staleApplications ?? []; return <Modal title="添加本机项目" visible={visible} onCancel={onClose} style={{ width: 760 }} footer={<><Button onClick={onClose}>取消</Button><Button theme="solid" loading={busy} disabled={Boolean(preview && stale.length && !replaceStale)} onClick={preview ? () => onImport(selectedApplications, replaceStale) : onScan}>{preview ? stale.length ? `确认替换 ${stale.length} 条旧记录并导入项目` : `导入项目「${preview.project.name}」` : '扫描目录'}</Button></>}><Typography.Paragraph type="tertiary">扫描结果首先是一个项目目录；Dockyard 只在本机读取配置，不会执行项目脚本或 PM2 配置。下方的可运行模块是该项目的可选托管单元。</Typography.Paragraph><div className="directory-input"><Input value={path} onChange={onPath} placeholder="项目绝对路径" showClear /><Button icon={<IconFolder />} loading={busy} onClick={onChoose}>选择目录</Button></div>{preview && <div className="preview-list"><article className="scan-project-candidate"><Tag color="blue">项目</Tag><div><b>{preview.project.name}</b><code>{preview.project.path}</code><Typography.Text type="tertiary">导入此代码库目录；可运行模块可在下方选择，也可稍后在项目内配置。</Typography.Text></div></article><div className="preview-heading"><b>此项目内的可运行模块</b><span>{preview.applications.length} 个候选项，已选择 {selectedApplications.length} 个</span></div>{preview.applications.length ? <div className="table-wrap scan-candidate-table"><table className="app-table"><thead><tr><th>托管</th><th>模块</th><th>默认启动命令</th></tr></thead><tbody>{preview.applications.map((candidate) => <tr key={candidate.key}><td><input aria-label={`托管 ${candidate.name}`} type="checkbox" checked={selected.includes(candidate.key)} onChange={(event) => toggle(candidate.key, event.target.checked)} /></td><td><Tag color={candidate.origin === 'pm2-ecosystem' ? 'blue' : 'grey'}>{candidate.origin === 'pm2-ecosystem' ? 'PM2' : 'module'}</Tag><b>{candidate.name}</b><small>{candidate.cwd}</small>{candidate.warnings.map((warning) => <Typography.Text type="warning" key={warning.field}>{warning.field}: {warning.reason}</Typography.Text>)}</td><td><code>{commandText(candidate.command)}</code><small>默认：{candidate.selectedCommand}（导入后可切换）</small></td></tr>)}</tbody></table></div> : <EmptyHint icon={<IconSearch />} title="项目内没有可运行模块" text="仍可导入这个项目并配置项目级规则；之后可再次扫描添加模块。" />}{stale.length > 0 && <label className="startup-rule"><input type="checkbox" checked={replaceStale} onChange={(event) => setReplaceStale(event.target.checked)} /><span>我确认替换 {stale.length} 条过时脚本级记录（只删除 Dockyard 的应用、指标和事件元数据；不删除源码或日志文件）。</span></label>}</div>}</Modal> }

function DirectoryScanModal({ visible, path, preview, busy, onPath, onChoose, onScan, onImport, onClose }: { visible: boolean; path: string; preview: DirectoryPreview | null; busy: boolean; onPath: (path: string) => void; onChoose: () => void; onScan: () => void; onImport: (projects: Preview[]) => void; onClose: () => void }): ReactElement {
  const [selected, setSelected] = useState<string[]>([]);
  useEffect(() => setSelected(preview?.projects.map((project) => project.project.path) ?? []), [preview]);
  const selectedProjects = preview?.projects.filter((project) => selected.includes(project.project.path)) ?? [];
  const toggle = (path: string, checked: boolean) => setSelected((current) => checked ? [...current, path] : current.filter((item) => item !== path));
  return <Modal title="批量扫描项目目录" visible={visible} onCancel={onClose} style={{ width: 820 }} footer={<><Button onClick={onClose}>取消</Button><Button theme="solid" loading={busy} disabled={Boolean(preview && !selectedProjects.length)} onClick={preview ? () => onImport(selectedProjects) : onScan}>{preview ? `添加 ${selectedProjects.length} 个项目` : '扫描目录'}</Button></>}><Typography.Paragraph type="tertiary">选择保存多个代码库的父目录，例如 ~/Desktop/Company。Dockyard 只扫描它的第一层子目录；每个识别到的代码库会成为独立项目。</Typography.Paragraph><div className="directory-input"><Input value={path} onChange={onPath} placeholder="代码库父目录（例如 ~/Desktop/Company）" showClear /><Button icon={<IconFolder />} loading={busy} onClick={onChoose}>选择目录</Button></div>{preview && <div className="preview-list"><article className="scan-project-candidate"><Tag color="blue">项目目录</Tag><div><b>{preview.root}</b><Typography.Text type="tertiary">已发现 {preview.projects.length} 个代码库项目；勾选后将分别导入，不会把父目录本身作为项目。</Typography.Text></div></article>{preview.projects.length ? <div className="table-wrap scan-project-table"><table className="app-table"><thead><tr><th>导入</th><th>项目</th><th>可运行模块</th></tr></thead><tbody>{preview.projects.map((item) => <tr key={item.project.path}><td><input aria-label={`导入 ${item.project.name}`} type="checkbox" checked={selected.includes(item.project.path)} onChange={(event) => toggle(item.project.path, event.target.checked)} /></td><td><b>{item.project.name}</b><small>{item.project.path}</small></td><td>{item.applications.length} 个 <small>{item.applications.map((application) => application.name).join(' · ') || '导入后可在项目内继续配置'}</small></td></tr>)}</tbody></table></div> : <EmptyHint icon={<IconSearch />} title="没有发现项目" text="第一层子目录需要包含 package.json、工作区配置、PM2 配置或 Git 元数据。" />}</div>}</Modal>;
}

function ApplicationTable({ apps, onAction, projectById }: { apps: Application[]; onAction: (app: Application, operation: 'start' | 'stop' | 'restart') => void; projectById: Map<string, Project> }): ReactElement { return <div className="table-wrap"><table className="app-table"><thead><tr><th>应用</th><th>所属项目</th><th>状态</th><th>PID</th><th>命令</th><th /></tr></thead><tbody>{apps.map((app) => <tr key={app.id}><td><b>{app.name}</b><small>{app.cwd}</small></td><td>{projectById.get(app.projectId)?.name ?? '—'}</td><td><StatusTag status={app.status} /></td><td>{app.pid ?? '—'}</td><td><code>{commandText(app.command)}</code></td><td><ApplicationActions app={app} onAction={onAction} /></td></tr>)}</tbody></table></div> }
function PolicyButton({ app }: { app: Application }): ReactElement { const [open, setOpen] = useState(false); const [restartPolicy, setRestartPolicy] = useState(app.restartPolicy); const [logPolicy, setLogPolicy] = useState(app.logPolicy); useEffect(() => { setRestartPolicy(app.restartPolicy); setLogPolicy(app.logPolicy); }, [app.id, app.restartPolicy, app.logPolicy]); const save = async () => { try { await api(`/api/applications/${encodeURIComponent(app.id)}/policies`, { method: 'PATCH', body: JSON.stringify({ restartPolicy, logPolicy }) }); Toast.success('应用守护与日志策略已更新。'); setOpen(false); } catch (error) { Toast.error(errorMessage(error)); } }; return <><Button size="small" onClick={() => setOpen(true)}>策略</Button><Modal title={`${app.name} 的守护与日志策略`} visible={open} onCancel={() => setOpen(false)} footer={<><Button onClick={() => setOpen(false)}>取消</Button><Button theme="solid" onClick={() => void save()}>保存策略</Button></>}><Typography.Paragraph type="tertiary">策略只作用于该可运行模块，并会即时更新守护进程中的活动实例。</Typography.Paragraph><label>重启模式<select value={restartPolicy.mode} onChange={(event) => setRestartPolicy({ ...restartPolicy, mode: event.target.value as RestartPolicy['mode'] })}><option value="never">never</option><option value="on-failure">on-failure</option><option value="always">always</option></select></label><div className="directory-input"><label>最大重试<Input type="number" value={String(restartPolicy.maxRetries)} onChange={(value) => setRestartPolicy({ ...restartPolicy, maxRetries: Number(value) })} /></label><label>退避 (ms)<Input type="number" value={String(restartPolicy.retryDelayMs)} onChange={(value) => setRestartPolicy({ ...restartPolicy, retryDelayMs: Number(value) })} /></label><label>稳定窗口 (ms)<Input type="number" value={String(restartPolicy.stableWindowMs)} onChange={(value) => setRestartPolicy({ ...restartPolicy, stableWindowMs: Number(value) })} /></label></div><div className="directory-input"><label>日志文件数<Input type="number" value={String(logPolicy.maxFiles)} onChange={(value) => setLogPolicy({ ...logPolicy, maxFiles: Number(value) })} /></label><label>单文件字节数<Input type="number" value={String(logPolicy.maxBytesPerFile)} onChange={(value) => setLogPolicy({ ...logPolicy, maxBytesPerFile: Number(value) })} /></label><label>保留天数<Input type="number" value={String(logPolicy.retentionDays)} onChange={(value) => setLogPolicy({ ...logPolicy, retentionDays: Number(value) })} /></label></div></Modal></>; }
function StatusTag({ status }: { status: Status }): ReactElement { const color = status === 'running' ? 'green' : status === 'crashed' ? 'red' : status === 'restarting' ? 'orange' : 'grey'; return <Tag color={color}>{status}</Tag> }
function StatCard({ label, value, accent, icon }: { label: string; value: string | number; accent: string; icon: ReactElement }): ReactElement { return <div className={`stat-card ${accent}`}><span className="stat-icon">{icon}</span><div><b>{value}</b><small>{label}</small></div></div> }
function EmptyHint({ icon, title, text }: { icon: ReactElement; title: string; text: string }): ReactElement { return <div className="empty-hint"><span>{icon}</span><b>{title}</b><Typography.Text type="tertiary">{text}</Typography.Text></div> }
function redactText(value: string): string { return value.replace(/((?:api[_-]?key|token|secret|password)\s*(?:=|:)\s*)\S+/giu, '$1[REDACTED]').replace(/(--(?:api[_-]?key|token|secret|password)\s+)\S+/giu, '$1[REDACTED]'); }
function commandText(command: Command): string { return [command.executable, ...command.args].map((part, index, all) => index > 0 && /(?:api[_-]?key|token|secret|password)$/iu.test(all[index - 1]) ? '[REDACTED]' : redactText(part)).join(' '); }
function formatDuration(milliseconds: number): string { const seconds = Math.max(0, Math.floor(milliseconds / 1_000)); const hours = Math.floor(seconds / 3_600); const minutes = Math.floor((seconds % 3_600) / 60); return hours ? `${hours}h ${minutes}m` : `${minutes}m ${seconds % 60}s`; }
function formatBytes(bytes: number): string { return `${(bytes / 1_048_576).toFixed(bytes >= 10 * 1_048_576 ? 0 : 1)} MB`; }
async function api<T = unknown>(path: string, init: RequestInit = {}): Promise<T> { const response = await fetch(path, { headers: { 'Content-Type': 'application/json', ...init.headers }, ...init }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(typeof body.message === 'string' ? body.message : `HTTP ${response.status}`); return body as T; }
function errorMessage(error: unknown): string { return error instanceof Error ? error.message : '请求失败。'; }
const dockyardRoot = globalThis as typeof globalThis & { __dockyardReactRoot?: ReturnType<typeof createRoot> };
const root = dockyardRoot.__dockyardReactRoot ?? createRoot(document.getElementById('root')!);
dockyardRoot.__dockyardReactRoot = root;
root.render(<StrictMode><DockyardApp /></StrictMode>);
